import { useCallback, useEffect, useState, useSyncExternalStore } from 'react'
import { isAnimationPaused, parseMotionChoice, type MotionChoice } from './motionPreference'

export function useMediaQuery(query: string, serverValue = false) {
  const subscribe = useCallback(
    (onChange: () => void) => {
      const mql = window.matchMedia(query)
      mql.addEventListener('change', onChange)
      return () => mql.removeEventListener('change', onChange)
    },
    [query],
  )
  return useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => serverValue,
  )
}

export const useReducedMotion = () => useMediaQuery('(prefers-reduced-motion: reduce)')

const MOTION_KEY = 'table-maker:motion'

function readChoice(): MotionChoice | null {
  try {
    return parseMotionChoice(localStorage.getItem(MOTION_KEY))
  } catch {
    return null
  }
}

/** Whether decorative animation is paused, and a toggle that remembers the explicit choice in this browser. */
export function useAnimationPause() {
  const reduced = useReducedMotion()
  // Loaded after hydration (the server render cannot know the stored choice).
  const [choice, setChoice] = useState<MotionChoice | null>(null)
  useEffect(() => setChoice(readChoice()), [])
  const paused = isAnimationPaused(reduced, choice)
  const toggle = () => {
    const next: MotionChoice = paused ? 'play' : 'pause'
    setChoice(next)
    try {
      localStorage.setItem(MOTION_KEY, next)
    } catch {
      // Storage unavailable (private window etc.) – the choice lasts for this page only.
    }
  }
  return { paused, toggle }
}

/**
 * Ref callback for a `.card`: tracks the pointer in --spot-x/--spot-y on the element itself.
 * The rect is read once per pointerenter (not per frame); the glow itself is pure CSS (see styles.css).
 */
export function spotlightRef(el: HTMLElement | null) {
  if (!el || typeof window === 'undefined' || !window.matchMedia('(hover: hover) and (pointer: fine)').matches) return
  let rect = el.getBoundingClientRect()
  const enter = () => {
    rect = el.getBoundingClientRect()
  }
  const move = (e: PointerEvent) => {
    el.style.setProperty('--spot-x', `${e.clientX - rect.left}px`)
    el.style.setProperty('--spot-y', `${e.clientY - rect.top}px`)
  }
  el.addEventListener('pointerenter', enter)
  el.addEventListener('pointermove', move)
  return () => {
    el.removeEventListener('pointerenter', enter)
    el.removeEventListener('pointermove', move)
  }
}
